    ('skills-canada-151', 'co-op-students-drive-manufacturing-innovation-at-toyota', 'Co-op students drive manufacturing innovation at Toyota', 'Step into Mechanical Engineering CAD with a quick look at how the work gets done, what the day feels like, and why the skills matter.', 'video', 'https://img.youtube.com/vi/Z2B4zQ8KRQw/maxresdefault.jpg', 'https://www.youtube.com/shorts/Z2B4zQ8KRQw', 'vertical', now() - (151 * interval '1 second'), true),
    ('skills-canada-152', 'what-is-a-mechanical-engineer', 'What is a Mechanical Engineer?', 'See how Mechanical Engineering CAD connects to real hiring signals, workplace expectations, and the kinds of roles students can start researching now.', 'video', 'https://img.youtube.com/vi/_3VprQxrDBA/maxresdefault.jpg', 'https://www.youtube.com/shorts/_3VprQxrDBA', 'vertical', now() - (152 * interval '1 second'), true),
    ('skills-canada-153', 'how-volkswagen-cars-are-painted-in-factory', 'How Volkswagen Cars are Painted in Factory', 'Step into How Volkswagen Cars are Painted in Factory with a quick look at how the work gets done, what the day feels like, and why the skills matter.', 'video', 'https://img.youtube.com/vi/s2L2K4qHsM8/maxresdefault.jpg', 'https://www.youtube.com/shorts/s2L2K4qHsM8', 'vertical', now() - (153 * interval '1 second'), true),
    ('skills-canada-154', 'toyota-developed-an-all-new-painting-process-for-cars', 'Toyota Developed An All New Painting Process For Cars', 'Look at the problem behind Toyota Developed An All New Painting Process For Cars and the practical skills people use to solve it in the real world.', 'video', 'https://img.youtube.com/vi/3p086A7NqCA/maxresdefault.jpg', 'https://www.youtube.com/shorts/3p086A7NqCA', 'vertical', now() - (154 * interval '1 second'), true),
    ('skills-canada-155', 'job-talks-cabinetmaker-lynn-describes-what-it-takes-to-be-a-cabinetmaker', 'Job Talks - Cabinetmaker - Lynn Describes What it Takes to be a Cabinetmaker', 'See how Job Talks - Cabinetmaker - Lynn Describes What it Takes to be a Cabinetmaker connects to real hiring signals, workplace expectations, and the kinds of roles students can start researching now.', 'video', 'https://img.youtube.com/vi/zESyNooEKc4/maxresdefault.jpg', 'https://www.youtube.com/watch?v=zESyNooEKc4', 'horizontal', now() - (155 * interval '1 second'), true),
